import { DomainError } from "./errors";

export const ORDER_STATES = ["placed", "paid", "packed", "shipped", "delivered", "cancelled"] as const;
export type OrderState = (typeof ORDER_STATES)[number];

export interface OrderLine {
  readonly productId: string;
  readonly quantity: number;
}

export interface Order {
  readonly id: string;
  readonly customerId: string;
  readonly lines: readonly OrderLine[];
  state: OrderState;
  readonly createdAt: Date;
}

const NEXT_STATE: Partial<Record<OrderState, OrderState>> = {
  placed: "paid",
  paid: "packed",
  packed: "shipped",
  shipped: "delivered",
};

const CANCELLABLE: readonly OrderState[] = ["placed", "paid", "packed"];

export function isOrderState(value: string): value is OrderState {
  return (ORDER_STATES as readonly string[]).includes(value);
}

export function advance(order: Order, target: OrderState): void {
  if (NEXT_STATE[order.state] !== target) {
    throw new DomainError("conflict", `Cannot move order ${order.id} from ${order.state} to ${target}`);
  }
  order.state = target;
}

export function cancel(order: Order): void {
  if (!CANCELLABLE.includes(order.state)) {
    throw new DomainError("conflict", `Cannot cancel order ${order.id} in state ${order.state}`);
  }
  order.state = "cancelled";
}

